interest_endpoint.s:
Create the endpoint that records an investor's interest.

Stored as a Qdrant row of type `x` in the same collection, keyed by a uuid derived from the product slug, the investor email and the timestamp so a double submit cannot silently overwrite a different investor's note.

Create src/routes/api/interest/+server.ts with exactly:

import type { RequestHandler } from './$types';
import { error, json } from '@sveltejs/kit';
import { env } from '$env/dynamic/private';
import { upsert, uuid_from } from '$lib/server/qdrant';

export const POST: RequestHandler = async ({ request }) => {
	const body = (await request.json()) as Record<string, string>;
	const pg = (body.pg ?? '').trim();
	const nm = (body.nm ?? '').trim();
	const em = (body.em ?? '').trim();
	if (!pg || !nm || !em) throw error(400, 'name, email and product are required');
	if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(em)) throw error(400, 'that email does not look right');

	const j = Math.floor(Date.now() / 1000);
	const id = await uuid_from(`interest:${pg}:${em.toLowerCase()}:${j}`);
	await upsert(env, [
		{
			id,
			payload: {
				s: 'adca',
				t: 'x',
				pg,
				nm,
				em: em.toLowerCase(),
				fm: (body.fm ?? '').trim().slice(0, 200),
				ms: (body.ms ?? '').trim().slice(0, 2000),
				j
			}
		}
	]);
	return json({ ok: true });
};

Validation is at a trust boundary and is not optional — this endpoint is unauthenticated by design, because requiring an investor to sign in before they can express interest is exactly the friction that loses the lead.

