Show a builder who asked about them. Without this the captured interest is invisible and the lead dies in the database.

FILE: src/routes/[slug]/+page.server.ts

Current load:

export const load: PageServerLoad = async ({ params }) => {
	const pt = await retrieve_one(env, await uuid_from(params.slug));
	if (!pt || !pt.payload) throw error(404, 'not found');
	const p = pt.payload as Record<string, unknown>;
	delete p.e;
	return { p };
};

Replace the whole function with:

export const load: PageServerLoad = async ({ params, locals }) => {
	const pt = await retrieve_one(env, await uuid_from(params.slug));
	if (!pt || !pt.payload) throw error(404, 'not found');
	const p = pt.payload as Record<string, unknown>;
	const owner = !!locals.user && locals.user.e === p.e;
	delete p.e;
	if (!owner) return { p, asks: [] };
	const pts = await scroll(env, f(eq('s', 'adca'), eq('t', 'x'), eq('pg', params.slug)), 200);
	const asks = pts
		.map((x) => x.payload as Record<string, string>)
		.sort((a, b) => Number(b.j ?? 0) - Number(a.j ?? 0));
	return { p, asks };
};

and extend the import at the top of the file from:

import { retrieve_one, uuid_from } from '$lib/server/qdrant';

to:

import { retrieve_one, uuid_from, scroll, eq, f } from '$lib/server/qdrant';

The ownership check happens BEFORE `delete p.e` and the delete still happens on every path — an investor must never receive the owner email, and the owner does not need it sent back to them.

