raising_page.s:
Create /raising — a page listing only the companies that say they are raising. It is the link to send an investor, and it is the page most likely to earn a search result for a query nobody else in this market has written a page for.

Create src/routes/raising/+page.server.ts with exactly:

import type { PageServerLoad } from './$types';
import { env } from '$env/dynamic/private';
import { scroll, eq, f } from '$lib/server/qdrant';

export const load: PageServerLoad = async () => {
	try {
		const pts = await scroll(env, f(eq('s', 'adca'), eq('t', 'p'), eq('ra', 'y')));
		const p = pts.map((pt) => {
			const x = pt.payload as Record<string, string>;
			delete x.e;
			return x;
		});
		return { p };
	} catch {
		return { p: [] as Record<string, string>[] };
	}
};

